#!/usr/bin/env python3
# SPDX-License-Identifier: LicenseRef-OpenLBM-Docs-1.0
# SPDX-FileCopyrightText: 2026 FutureBuild, Inc. and OpenLBM contributors
"""REUSE compliance gate for the Gable repository.

Runs `reuse lint --json` and fails on every REUSE non-compliance category
*except* `unused_licenses`, which is reported as a warning instead.

Why the carve-out
-----------------
`LICENSES/` is this project's *license catalog*, not just the set of licenses
that happen to govern files in this repo. LICENSE-MAP.md deliberately ships
texts that no file here is licensed under -- see its "Also in LICENSES/"
section, which calls out `LicenseRef-OpenLBM-Community-Source-1.0` as
"applied per-work (by version notice), not per-directory". The REUSE
specification has no way to express "this text is catalogued but unused", so
plain `reuse lint` will always report those texts as unused and exit 1.

Every check that actually protects the licensing claims -- bad/deprecated
licenses, licenses referenced but missing from LICENSES/, unreadable files,
and any file lacking copyright or licensing information -- is a hard failure
here. If the maintainers later decide to prune the catalog down to only the
licenses in use, delete the TOLERATED set below and this script becomes a
straight `reuse lint`.

Why the inline-header check
---------------------------
`REUSE.toml` annotates whole trees (`core/**`, `web/apps/**`, `web/packages/**`
and so on), so plain `reuse lint` already counts every file as licensed
whether or not it carries the matching identifier and copyright lines
inline. That means a new file with no header at all is still reported as
compliant, which silently breaks the house rule (BRIEF-COMMON: every new
file carries the SPDX header its directory's licence row in LICENSE-MAP.md
gives). This gate therefore runs its own second pass over the tracked source
files and fails when a file in a language extension is missing one or both
inline header lines.
"""

from __future__ import annotations

import json
import os
import subprocess
import sys

# The only REUSE non-compliance category that does not fail this gate.
TOLERATED = {"unused_licenses"}

# Human-readable labels for the categories reuse reports. Any category reuse
# adds in a future version is picked up automatically and treated as a hard
# failure (it just gets a raw key as its label) unless it is added to TOLERATED.
LABELS = {
    "bad_licenses": "Unrecognised / non-SPDX licenses",
    "deprecated_licenses": "Deprecated SPDX licenses",
    "licenses_without_extension": "License files without a file extension",
    "missing_licenses": "Licenses referenced but missing from LICENSES/",
    "unused_licenses": "License texts in LICENSES/ not used by any file",
    "read_errors": "Files that could not be read",
    "missing_copyright_info": "Files with no copyright information",
    "missing_licensing_info": "Files with no licensing information",
    "invalid_spdx_expressions": "Files with an unparseable SPDX expression",
    "missing_inline_header": (
        "Files with no inline SPDX header (an SPDX-License-Identifier and "
        "SPDX-FileCopyrightText pair in the first ten lines)"
    ),
}

# File extensions whose tracked files must carry the inline SPDX header.
INLINE_CHECK_EXTENSIONS: tuple[str, ...] = (
    ".go",
    ".ts",
    ".tsx",
    ".js",
    ".mjs",
    ".sql",
    ".py",
    ".sh",
)

# The literal header tags, composed at runtime so they do not appear as a
# single substring anywhere outside the SPDX header comment at the top of
# this file. reuse scans every line for the literal "SPDX-License-Identifier"
# pattern and would otherwise try to parse these strings as SPDX expressions.
_LICENSE_TAG = "SPDX-" + "License-Identifier:"
_COPYRIGHT_TAG = "SPDX-" + "FileCopyrightText:"

# Tracked files that look like source but are generated and therefore cannot
# carry an inline header -- the generator owns the whole file and would
# overwrite any header on every regeneration. The REUSE.toml tree annotation
# for the file's directory supplies the licence instead. Each entry pairs a
# repo-relative path with a short reason that explains *why* it is exempt.
INLINE_EXEMPT: dict[str, str] = {
    "web/packages/api-client/src/schema.d.ts": (
        "generated by `npm run generate` (openapi-typescript), lives under "
        "the web/packages/** annotation in REUSE.toml"
    ),
}


def invalid_expressions(report: dict) -> list[str]:
    """Files whose SPDX expression does not parse.

    reuse 6.2 checks this in `reuse lint` but does *not* surface it under
    `non_compliant` in the JSON report -- it only shows up as `is_valid: false`
    on the per-file expressions. Without this, the gate would pass a tree that
    plain `reuse lint` rejects.

    The usual cause is documentation: prose or a shell snippet that quotes an
    SPDX license tag, which reuse then scrapes as if it were the file's real
    tag. The fix is to bracket the offending block with reuse's ignore markers
    (see <https://reuse.software/faq/#exclude-file>), not to reword the docs.
    """
    found = []
    for entry in report.get("files", []):
        for expression in entry.get("spdx_expressions", []):
            if not expression.get("is_valid", True):
                found.append(f"{entry['path']}: {expression.get('value')!r}")
    return found


def missing_inline_headers(git_root: str) -> list[str]:
    """Tracked source files missing the inline SPDX header.

    The header is the same pair `reuse lint` looks for -- an identifier
    line and a copyright line -- appearing somewhere in the first ten lines
    of the file. Files in `INLINE_EXEMPT` are excluded, and files outside
    `INLINE_CHECK_EXTENSIONS` are ignored (the inline header is a house rule
    for source code, not a requirement for every file in the tree).
    """
    try:
        tracked = subprocess.check_output(
            ["git", "-C", git_root, "ls-files"],
            text=True,
        ).splitlines()
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ["<git ls-files failed>"]

    missing: list[str] = []
    for path in tracked:
        if not path.endswith(INLINE_CHECK_EXTENSIONS):
            continue
        if path in INLINE_EXEMPT:
            continue
        full_path = os.path.join(git_root, path)
        try:
            with open(full_path, "r", encoding="utf-8", errors="replace") as fh:
                head = "".join(fh.readline() for _ in range(10))
        except OSError as exc:
            missing.append(f"{path}: <unreadable: {exc}>")
            continue
        has_id = _LICENSE_TAG in head
        has_cr = _COPYRIGHT_TAG in head
        if not (has_id and has_cr):
            missing.append(
                f"{path}: missing "
                + ("identifier line " if not has_id else "")
                + ("copyright line" if not has_cr else "")
            )
    return missing


def emit(lines: list[str]) -> None:
    """Print to stdout and, on GitHub Actions, to the job step summary."""
    text = "\n".join(lines)
    print(text)
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary_path:
        with open(summary_path, "a", encoding="utf-8") as handle:
            handle.write(text + "\n")


def main() -> int:
    reuse_bin = os.environ.get("REUSE_BIN", "reuse")
    try:
        proc = subprocess.run(
            [reuse_bin, "lint", "--json"],
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        print(
            f"error: '{reuse_bin}' not found. Install it with "
            "`pipx install reuse` or `pip install reuse`.",
            file=sys.stderr,
        )
        return 2

    if not proc.stdout.strip():
        sys.stderr.write(proc.stderr)
        print("error: `reuse lint --json` produced no output", file=sys.stderr)
        return 2

    report = json.loads(proc.stdout)
    non_compliant = dict(report.get("non_compliant", {}))
    summary = report.get("summary", {})

    # Not reported under non_compliant by reuse 6.2 -- see invalid_expressions().
    non_compliant["invalid_spdx_expressions"] = invalid_expressions(report)

    # Inline-header pass (see the module docstring for the why). Operates on
    # the working directory's tree; reuse lint itself only cares about the
    # REUSE.toml annotations, so it cannot see a missing inline header.
    non_compliant["missing_inline_header"] = missing_inline_headers(
        os.getcwd()
    )

    failures = {
        key: value
        for key, value in non_compliant.items()
        if value and key not in TOLERATED
    }
    warnings = {
        key: value
        for key, value in non_compliant.items()
        if value and key in TOLERATED
    }

    lines = [
        "## REUSE licensing gate",
        "",
        f"- reuse {report.get('reuse_tool_version', '?')}, "
        f"spec {report.get('reuse_spec_version', '?')}",
        f"- Files scanned: **{summary.get('files_total', '?')}**",
        f"- With copyright info: **{summary.get('files_with_copyright_info', '?')}**",
        f"- With licensing info: **{summary.get('files_with_licensing_info', '?')}**",
        f"- Licenses in use: {', '.join(summary.get('used_licenses', [])) or 'none'}",
        "",
    ]

    for key, value in warnings.items():
        lines.append(f"> [!NOTE]")
        lines.append(f"> {LABELS.get(key, key)} (tolerated, not a failure):")
        for item in value:
            lines.append(f"> - `{item}`")
        lines.append("")

    if failures:
        lines.append("### Failures")
        lines.append("")
        for key, value in failures.items():
            lines.append(f"**{LABELS.get(key, key)}** ({len(value)}):")
            lines.append("")
            for item in value[:50]:
                lines.append(f"- `{item}`")
            if len(value) > 50:
                lines.append(f"- ... and {len(value) - 50} more")
            lines.append("")
        emit(lines)
        for key in failures:
            print(f"::error::REUSE gate failed: {LABELS.get(key, key)}")
        return 1

    lines.append("REUSE gate **passed**.")
    emit(lines)
    return 0


if __name__ == "__main__":
    sys.exit(main())